from __future__ import annotations

import typing

import protobug


@protobug.message
class Message1:
    a: typing.Union[protobug.Int32, None] = protobug.field(1, default=None)


@protobug.message
class Message2:
    b: protobug.String = protobug.field(2)


@protobug.message
class Message3:
    c: Message1 = protobug.field(3)


@protobug.message
class Message4:
    d: typing.Union[protobug.String, None] = protobug.field(4, default=None)
    e: list[protobug.Int32] = protobug.field(5, default_factory=list)


@protobug.message
class Message5:
    f: list[protobug.Int32] = protobug.field(6)


class MessageEnum(protobug.Enum):
    A = 0
    B = 1
    C = 2


@protobug.message
class Message6:
    g: dict[protobug.String, protobug.UInt32] = protobug.field(7)


@protobug.message
class Message7:
    h: list[MessageEnum] = protobug.field(8)


@protobug.message
class Message8:
    i: protobug.Float = protobug.field(9)

from __future__ import annotations

import typing

import pytest

import protobug


class Test1:
    a: int = protobug.field(1)


class Test2:
    a: list = protobug.field(1)


class Test3:
    a: dict = protobug.field(1)


class Test4:
    a: protobug.Int32 = protobug.field(1)
    b: protobug.Int32 = protobug.field(1)


class Test5:
    a: protobug.Int32 = protobug.field(-1)


class Test6:
    a: typing.Optional[list[protobug.Int32]] = protobug.field(1)


class Test7:
    a: typing.Optional[dict[protobug.Int32, protobug.Int32]] = protobug.field(1)


message_type_errors_tests = [
    (
        Test1,
        TypeError("invalid field type"),
        "do not allow plain int as type",
    ),
    (
        Test2,
        TypeError("missing specialization"),
        "do not allow unspecialized list type",
    ),
    (
        Test3,
        TypeError("missing specialization"),
        "do not allow unspecialized dict type",
    ),
    (
        Test4,
        ValueError("duplicate id: 1"),
        "do not allow duplicate proto id",
    ),
    (
        Test5,
        ValueError("negative id not allowed: -1"),
        "do not allow negative proto id",
    ),
    (
        Test6,
        TypeError("remove the optional annotation"),
        "do not allow optional list",
    ),
    (
        Test7,
        TypeError("remove the optional annotation"),
        "do not allow optional dict",
    ),
]


@pytest.mark.parametrize(
    "py_type,error",
    [test[:-1] for test in message_type_errors_tests],
    ids=[test[-1] for test in message_type_errors_tests],
)
def test_message_type_errors(py_type: type, error: Exception) -> None:
    with pytest.raises(type(error), match=error.args[0]):
        protobug.message(py_type)


zigzag_tests = [
    (0, 0),
    (-1, 1),
    (1, 2),
    (-2, 3),
    (2, 4),
    (0x7FFFFFFF, 0xFFFFFFFE),
    (-0x80000000, 0xFFFFFFFF),
]


@pytest.mark.parametrize(
    "input,output",
    zigzag_tests,
    ids=[f"{a} to {b}" for a, b in zigzag_tests],
)
def test_signed_to_zigzag(input: int, output: int) -> None:
    assert protobug.signed_to_zigzag(input) == output


@pytest.mark.parametrize(
    "input,output",
    [(b, a) for a, b in zigzag_tests],
    ids=[f"{b} to {a}" for a, b in zigzag_tests],
)
def test_zigzag_to_signed(input: int, output: int) -> None:
    assert protobug.zigzag_to_signed(input) == output


def test_enum() -> None:
    class TestEnum1(protobug.Enum):
        A = 1
        B = 2

    assert TestEnum1.A == 1

    with pytest.raises(Exception):

        class TestEnum2(protobug.Enum):
            A = 1
            B = ""  # type: ignore

    assert TestEnum1(3) == 3
    assert TestEnum1(3) == TestEnum1(3)
    assert TestEnum1(3) is TestEnum1(3)
    assert TestEnum1(3) not in TestEnum1
    assert TestEnum1(3) != TestEnum1(4)
    assert str(TestEnum1(3)) == "TestEnum1.?"
    assert repr(TestEnum1(3)) == "<TestEnum1.?: 3>"

    class TestEnum3(protobug.Enum, strict=True):
        A = 1
        B = 2

    with pytest.raises(ValueError, match="3 is not a valid"):
        TestEnum3(3)


def test_annotation_resolving() -> None:
    # See: https://github.com/yt-dlp/protobug/issues/1
    @protobug.message
    class Message1:
        field: protobug.Int32 | None = protobug.field(1, default=None)

    @protobug.message
    class Message2:
        field: None | protobug.Int32 = protobug.field(1, default=None)

    @protobug.message
    class Message3:
        message1: Message1 | None = protobug.field(1, default=None)
        message2: Message2 | None = protobug.field(2, default=None)

    @protobug.message
    class Message4:
        class Message4Nested(protobug.Enum, strict=False):
            A = 1

        nested: Message4Nested | None = protobug.field(1, default=None)

from __future__ import annotations

import dataclasses
import io
import typing

from protobug._core import _NAME_LOOKUP_NAME
from protobug._core import ProtoMode
from protobug._core import ProtoType
from protobug._core import WireType
from protobug._core import _double_struct
from protobug._core import _float_struct
from protobug._core import signed_to_zigzag

if typing.TYPE_CHECKING:
    from protobug._core import ProtoConversionInfo


class Writer:
    def __init__(self, writer: io.BufferedIOBase, /):
        self._position = 0
        self._writer = writer

    def write(self, value: typing.Any, /) -> int:
        # TODO(Grub4K): add support to write plain dict using a `py_type`
        py_type = type(value)
        schema: dict[str, ProtoConversionInfo] | None = getattr(
            py_type, _NAME_LOOKUP_NAME, None
        )
        if not schema:
            msg = f"not a valid protobuf type: {py_type}"
            raise TypeError(msg)

        size = 0
        for field in dataclasses.fields(value):
            conversion_info = schema[field.name]
            # Check if this field is defaulted
            field_value = getattr(value, conversion_info.name)
            if conversion_info.proto_mode is ProtoMode.Optional and (
                field_value == field.default or field_value is None
            ):
                continue

            if isinstance(field_value, list):
                if (
                    conversion_info.proto_mode is ProtoMode.Packed
                    and len(field_value) > 2
                ):
                    # hahahahahahahahahahahahahahahahahahahahaha
                    with io.BytesIO() as buffer:
                        writer = Writer(buffer)
                        for item in field_value:
                            writer.write_type(item, conversion_info.proto_type)
                        data = buffer.getvalue()

                    size += self.write_tag(conversion_info.pid, WireType.LEN)
                    size += self.write_varint(len(data))
                    size += self._writer.write(data)
                    continue

                for item in field_value:
                    size += self.write_tag(
                        conversion_info.pid,
                        conversion_info.proto_type.wire_type(),
                    )
                    size += self.write_type(item, conversion_info.proto_type)
                continue

            if isinstance(field_value, dict):
                for k, v in field_value.items():
                    map_item = conversion_info.py_type(k, v)
                    size += self.write_tag(conversion_info.pid, WireType.LEN)
                    size += self.write_type(map_item, ProtoType.Embed)
                continue

            size += self.write_tag(
                conversion_info.pid,
                conversion_info.proto_type.wire_type(),
            )
            size += self.write_type(field_value, conversion_info.proto_type)

        return size

    def write_type(self, value: typing.Any, proto_type: ProtoType, /) -> int:
        if proto_type in (
            ProtoType.Int32,
            ProtoType.Int64,
            ProtoType.UInt32,
            ProtoType.UInt64,
            ProtoType.SInt32,
            ProtoType.SInt64,
            ProtoType.Enum,
        ):
            assert isinstance(value, int), f"{type(value)=}"
            if proto_type in (ProtoType.Int32, ProtoType.Enum, ProtoType.Int64):
                if value < 0:
                    value += 1
                    value += (
                        0xFFFFFFFF_FFFFFFFF
                        if proto_type is ProtoType.Int64
                        else 0xFFFFFFFF
                    )
            elif proto_type in (ProtoType.SInt32, ProtoType.SInt64):
                value = signed_to_zigzag(value)
            else:
                assert value >= 0
            return self.write_varint(value)

        if proto_type is ProtoType.Bool:
            assert isinstance(value, bool)
            value = b"\x01" if value else b"\x00"

        elif proto_type is ProtoType.Float:
            assert isinstance(value, float)
            value = _float_struct.pack(value)

        elif proto_type is ProtoType.Double:
            assert isinstance(value, float)
            value = _double_struct.pack(value)

        elif proto_type in (
            ProtoType.Fixed32,
            ProtoType.Fixed64,
            ProtoType.SFixed32,
            ProtoType.SFixed64,
        ):
            assert isinstance(value, int)
            if proto_type in (ProtoType.Fixed32, ProtoType.Fixed64):
                assert value >= 0
            length = 4 if proto_type in (ProtoType.Fixed32, ProtoType.SFixed32) else 8
            value = value.to_bytes(length, "little", signed=True)

        elif proto_type is ProtoType.String:
            assert isinstance(value, str)
            value = value.encode()

        elif proto_type is ProtoType.Embed:
            # TODO(Grub4K): """streaming""" writer, he says
            value = dumps(value)

        assert isinstance(value, bytes)
        size = 0
        if proto_type.wire_type() is WireType.LEN:
            size += self.write_varint(len(value))
        size += self._writer.write(value)
        return size

    def write_tag(self, pid: int, wire_type: WireType, /) -> int:
        result = (pid << 3) | wire_type
        return self.write_varint(result)

    def write_varint(self, value: int, /) -> int:
        size = ((value.bit_length() - 1) // 7 + 1) or 1
        buffer = bytearray(size)

        for i in range(size - 1):
            buffer[i] = (value & 0b0111_1111) | 0b1000_0000
            value >>= 7

        buffer[-1] = value
        return self._writer.write(buffer)


def dump(data: typing.Any, file: io.BufferedIOBase, /) -> int:
    return Writer(file).write(data)


def dumps(data: typing.Any, /) -> bytes:
    with io.BytesIO() as buffer:
        Writer(buffer).write(data)
        return buffer.getvalue()

from __future__ import annotations

import io
import typing

from protobug._core import _PID_LOOKUP_NAME
from protobug._core import ProtoType
from protobug._core import WireType
from protobug._core import _double_struct
from protobug._core import _float_struct
from protobug._core import _MapBase
from protobug._core import zigzag_to_signed

if typing.TYPE_CHECKING:
    from protobug._core import ProtoConversionInfo

    T = typing.TypeVar("T")


class Reader:
    def __init__(self, reader: io.BufferedIOBase, /):
        self._position = 0
        self._reader = reader

    @typing.overload
    def read(self, py_type: type[T], /, *, length: int | None = None) -> T: ...

    @typing.overload
    def read(
        self, py_type: None, /, *, length: int | None = None
    ) -> dict[int, list]: ...

    def read(
        self, py_type: type | None = None, /, *, length: int | None = None
    ) -> typing.Any:
        schema: dict[int, ProtoConversionInfo] | None = None
        if py_type is not None:
            schema = getattr(py_type, _PID_LOOKUP_NAME, None)
            if not schema:
                msg = f"not a valid protobuf type: {py_type}"
                raise TypeError(msg)

        begin = self._position
        expected_position = begin + (length or 0)

        result: dict[int, list] = {}
        named_result: dict[str, typing.Any] = {}
        while length is None or self._position < expected_position:
            try:
                key, value = self.read_record(schema)
                conversion_info = schema.get(key) if schema is not None else None
                if conversion_info is None:
                    # We could guess here if we have type info from other sources?
                    if key not in result:
                        result[key] = []
                    if isinstance(value, list):
                        result[key].extend(value)
                    else:
                        result[key].append(value)

                else:
                    name = conversion_info.name
                    if isinstance(value, list):
                        if not value:
                            continue
                        if isinstance(value[0], _MapBase):
                            target = named_result.setdefault(name, {})
                            for item in value:
                                if not isinstance(item, _MapBase):
                                    msg = f"inconsistent value types: expected Map, got {type(item)}"
                                    raise TypeError(msg)
                                target[item.key] = item.value
                        else:
                            named_result.setdefault(name, []).extend(value)

                    elif isinstance(value, _MapBase):
                        named_result.setdefault(name, {})[value.key] = value.value

                    else:
                        named_result[name] = value

            except EOFError:
                break

        if length is not None and self._position != expected_position:
            msg = f"non matching data length: expected {length}, got {self._position - begin}"
            raise ValueError(msg)

        if py_type is None:
            return result
        result_type = py_type(**named_result)
        result_type._unknown = result
        return result_type

    def read_record(
        self, schema: dict[int, ProtoConversionInfo] | None = None, /
    ) -> tuple[int, typing.Any]:
        key, wire_type = self.read_tag()
        info = schema.get(key) if schema is not None else None
        if info is None:
            # We have no info on this key, read the raw value
            return key, self.read_value(wire_type)

        expected_wire_type = info.proto_type.wire_type()
        if not info.proto_mode.is_multiple():
            # Single item, read and decode type
            if wire_type is not expected_wire_type:
                msg = (
                    f"unexpected value type for {info.name}: "
                    f"expected {expected_wire_type}, got {wire_type}"
                )
                raise ValueError(msg)
            return key, self.read_type(info.proto_type, info.py_type)

        if wire_type is expected_wire_type:
            # single, repeated, non-packed value, wrap in list
            return key, [self.read_type(info.proto_type, info.py_type)]

        if wire_type is not WireType.LEN:
            expected_type_msg = (
                str(WireType.LEN)
                if expected_wire_type is WireType.LEN
                else f"{expected_wire_type} or {WireType.LEN}"
            )
            msg = f"unexpected value type for {info.name}: expected {expected_type_msg}, got {wire_type}"
            raise ValueError(msg)

        # iteratively decode until we reach length
        length = typing.cast(int, self.read_value(WireType.VARINT))
        begin = self._position
        expected_position = begin + length

        results = []
        while self._position < expected_position:
            results.append(self.read_type(info.proto_type, info.py_type))

        if self._position != expected_position:
            msg = f"non-matching packed length: expected {length}, got {self._position - begin}"
            raise ValueError(msg)

        return key, results

    def read_type(
        self, proto_type: ProtoType, py_type: type | None = None, /
    ) -> typing.Any:
        if proto_type is ProtoType.Embed:
            assert py_type is not None, "py_type is required when passing _PType.Embed"
            length = typing.cast(int, self.read_value(WireType.VARINT))
            return self.read(py_type, length=length)

        value = self.read_value(proto_type.wire_type())
        if proto_type is ProtoType.Enum:
            return value if py_type is None else py_type(value)

        if proto_type in (
            ProtoType.Bytes,
            ProtoType.Int32,
            ProtoType.Int64,
            ProtoType.UInt32,
            ProtoType.UInt64,
        ):
            return value

        if proto_type is ProtoType.Bool:
            assert isinstance(value, int)
            return bool(value)

        if proto_type is ProtoType.String:
            assert isinstance(value, bytes)
            return value.decode()

        if proto_type is ProtoType.Float:
            assert isinstance(value, bytes)
            return _float_struct.unpack(value)[0]

        if proto_type is ProtoType.Double:
            assert isinstance(value, bytes)
            return _double_struct.unpack(value)[0]

        if proto_type in (
            ProtoType.SInt32,
            ProtoType.SInt64,
            ProtoType.SFixed32,
            ProtoType.SFixed64,
        ):
            if proto_type in (ProtoType.SFixed32, ProtoType.SFixed64):
                assert isinstance(value, bytes)
                value = int.from_bytes(value, "little")
            assert isinstance(value, int)
            return zigzag_to_signed(value)

        if proto_type in (ProtoType.Fixed32, ProtoType.Fixed64):
            assert isinstance(value, bytes)
            return int.from_bytes(value, "little", signed=True)

        raise ValueError(f"invalid protobuf value: {value!r}")

    def read_value(self, wire_type: WireType, /) -> int | bytes:
        if wire_type in (WireType.SGROUP, WireType.EGROUP):
            # SGROUP and EGROUP are deprecated
            msg = f"{wire_type.name} is deprecated and not implemented"
            raise NotImplementedError(msg)

        if wire_type == WireType.VARINT:
            return self.read_varint()

        if wire_type == WireType.I64:
            size = 8
        elif wire_type == WireType.I32:
            size = 4
        else:
            size = self.read_varint()

        data = self._reader.read(size)
        length = len(data)
        self._position += length
        if length < size:
            msg = f"not enough data: expected {size}, got {length}"
            raise ValueError(msg)
        return data

    def read_tag(self, /) -> tuple[int, WireType]:
        value = self.read_varint()
        return value >> 3, WireType(value & 0b111)

    def read_varint(self, /) -> int:
        data = self._reader.read(1)
        if not data:
            raise EOFError
        self._position += 1

        byte = data[0]
        result = byte & 0b0111_1111
        shift = 7
        while byte & 0b1000_0000:
            data = self._reader.read(1)
            if not data:
                msg = "expected another byte but reached EOF"
                raise ValueError(msg)

            self._position += 1
            byte = data[0]
            result |= (byte & 0b0111_1111) << shift
            shift += 7

        return result


@typing.overload
def load(file: io.BufferedIOBase, py_type: type[T], /) -> T: ...


@typing.overload
def load(file: io.BufferedIOBase, py_type: None = None, /) -> dict: ...


def load(file: io.BufferedIOBase, py_type=None, /):  # type: ignore
    return Reader(file).read(py_type)


@typing.overload
def loads(data: bytes | bytearray | memoryview, py_type: type[T], /) -> T: ...


@typing.overload
def loads(data: bytes | bytearray | memoryview, py_type: None = None, /) -> dict: ...


def loads(data: bytes | bytearray | memoryview, py_type=None, /):  # type: ignore
    with io.BytesIO(data) as buffer:
        return Reader(buffer).read(py_type)
